<?php
namespace Tests;
use App\Services\{SalonStore,Tenant,Waitlist,Notifications,Connections,ProviderReminders,BookingPrepayments,Payments,SubscriptionRenewal,Subscriptions,SystemIssues,ClientInvitations};
use Carbon\CarbonImmutable as Time;
use Illuminate\Foundation\Testing\TestCase;
use Illuminate\Support\Facades\{Artisan,DB,Crypt,Http,Mail,Cache};
use Illuminate\Support\Str;
final class LaunchToolsTest extends TestCase {
 private string $path;
 public function createApplication(){$a=require __DIR__.'/../bootstrap/app.php';$a->make(\Illuminate\Contracts\Console\Kernel::class)->bootstrap();return $a;}
 protected function setUp():void{parent::setUp();if(config('database.default')!=='sqlite'||config('database.connections.sqlite.database')!==':memory:')throw new \RuntimeException('In-memory database only.');Artisan::call('migrate',['--force'=>true]);Time::setTestNow('2036-05-06T06:00:00Z');$this->path=storage_path('framework/launch-'.bin2hex(random_bytes(6)));config(['integrations.path'=>$this->path,'operator.connections_path'=>$this->path.'-platform']);foreach(['waitlist_entries','provider_reminders','reminder_completions','system_issues','salon_state','providers','deliveries','guest_invitations','guest_accounts','provider_members','provider_security','calendar_connections','calendar_tasks'] as $t)DB::table($t)->delete();foreach([1,2] as $id)DB::table('salon_state')->insert(['id'=>$id,'data'=>json_encode(SalonStore::initial())]);app(SalonStore::class)->mutate(function(&$s){$s['settings']['waitlistEnabled']=true;});DB::table('providers')->insert(['id'=>2,'name'=>'Other','email'=>'other@example.com','password_hash'=>'test','active'=>true,'trial_started_at'=>now(),'trial_ends_at'=>now()->addYear(),'created_at'=>now(),'updated_at'=>now()]);Cache::flush();Http::preventStrayRequests();Mail::fake();$this->admin();}
 protected function tearDown():void{Time::setTestNow();foreach(glob($this->path.'*') as $f)if(is_file($f))unlink($f);parent::tearDown();}
 private function admin():void{$this->withSession(['admin'=>true,'provider_id'=>1,'_token'=>str_repeat('d',40)])->withHeader('X-CSRF-TOKEN',str_repeat('d',40));}
 private function email():void{app(\App\Services\PlatformConnections::class)->save(['smtp_host'=>'smtp.example.com','smtp_port'=>587,'mail_from'=>'sender@example.com']);}
 private function reminder(array $replace=[]):array{return array_replace(['title'=>'Hajfesték rendelése','staffId'=>'anna','startsAt'=>'2036-05-06T10:00','duration'=>15,'frequency'=>'weekly','count'=>0],$replace);}
 private function waitlist(array $replace=[]):array{return array_replace(['name'=>'Váró Vendég','email'=>'waiting@example.com','services'=>['cut'],'staff'=>'anna','firstDate'=>'2036-05-07','lastDate'=>'2036-05-07','timeFrom'=>'10:00','timeTo'=>'10:30','consent'=>true],$replace);}
 private function booking():array{return ['id'=>'book1','name'=>'Vendég','phone'=>'06301234567','email'=>'guest@example.com','staff'=>'anna','services'=>['cut'],'serviceSnapshot'=>[['id'=>'cut','name'=>'Hajvágás','duration'=>45,'price'=>10000]],'start'=>'2036-05-07T08:00:00Z','status'=>'confirmed','token'=>str_repeat('a',48),'updatedAt'=>now()->toISOString()];}
 private function postWebhook(array $o){$body=json_encode(['id'=>'evt-'.Str::uuid(),'type'=>'checkout.session.completed','data'=>['object'=>$o]]);return $this->call('POST','/api/stripe/webhook',[],[],[],['CONTENT_TYPE'=>'application/json','HTTP_STRIPE_SIGNATURE'=>'t='.time().',v1='.hash_hmac('sha256',time().'.'.$body,'webhook-secret')],$body);}
 public function test_reminders_can_overlap_bookings_and_never_occupy_public_slots():void{$b=$this->booking();app(SalonStore::class)->mutate(function(&$s)use($b){$s['bookings']=[$b];});$id=$this->postJson('/api/provider-reminders',$this->reminder(['startsAt'=>'2036-05-07T10:00','frequency'=>'none']))->assertOk()->json('id');$this->getJson('/api/provider-reminders?from=2036-05-07&to=2036-05-07')->assertOk()->assertJsonPath('occurrences.0.title','Hajfesték rendelése');$this->assertCount(1,app(SalonStore::class)->read()['bookings']);$s=app(SalonStore::class)->read();$s['bookings']=[];$slots=Waitlist::slots($s,$this->waitlist(),'2036-05-07');$this->assertNotEmpty($slots);$this->assertTrue(collect($slots)->contains('time','10:00'));$this->withSession(['provider_id'=>2]);$this->deleteJson('/api/provider-reminders/'.$id)->assertNotFound();$this->getJson('/api/public')->assertJsonMissingPath('provider_reminders');}
 public function test_weekly_reminder_keeps_local_time_over_dst_and_honours_count_until_and_completion():void{$id=$this->postJson('/api/provider-reminders',$this->reminder(['startsAt'=>'2036-03-23T09:00','untilDate'=>'2036-04-20','count'=>3]))->assertOk()->json('id');$row=DB::table('provider_reminders')->find($id);$events=ProviderReminders::occurrences($row,'2036-03-20','2036-04-30');$this->assertCount(3,$events);foreach($events as $event)$this->assertSame('09:00',Time::parse($event['start'])->setTimezone('Europe/Budapest')->format('H:i'));$this->patchJson('/api/provider-reminders/'.$id,['date'=>$events[1]['date'],'completed'=>true])->assertOk();$this->assertTrue(ProviderReminders::occurrences($row,$events[1]['date'],$events[1]['date'])[0]['completed']);$this->patchJson('/api/provider-reminders/'.$id,['date'=>'2036-03-24','completed'=>true])->assertUnprocessable();$this->getJson('/api/provider-reminders?from=2036-01-01&to=2037-01-01')->assertUnprocessable();}
 public function test_waitlist_requires_confirmation_and_only_then_notifies_once_via_email():void{$this->email();$this->withSession(['admin'=>false]);$this->postJson('/api/waitlist/join',$this->waitlist())->assertStatus(202);$row=DB::table('waitlist_entries')->first();$v=Waitlist::data($row);$this->assertSame('pending',$row->status);$this->assertSame(0,Waitlist::run()['queued']);app(Notifications::class)->run();Mail::assertSent(\App\Mail\NotificationMail::class,1);$this->postJson('/api/waitlist/token/'.$v['token'],['action'=>'confirm'])->assertOk();$this->assertSame(1,Waitlist::run()['queued']);app(Notifications::class)->run();Mail::assertSent(\App\Mail\NotificationMail::class,2);$this->assertSame('notified',DB::table('waitlist_entries')->value('status'));Waitlist::run();app(Notifications::class)->run();Mail::assertSent(\App\Mail\NotificationMail::class,2);$this->getJson('/api/waitlist')->assertForbidden();$this->getJson('/api/waitlist/token/'.$v['token'])->assertJsonMissingPath('email');}
 public function test_waitlist_does_not_offer_occupied_slots_and_rechecks_before_send():void{$this->email();$b=$this->booking();app(SalonStore::class)->mutate(function(&$s)use($b){$s['bookings']=[$b];});$this->postJson('/api/waitlist/join',$this->waitlist(['timeTo'=>'10:01']))->assertStatus(202);$row=DB::table('waitlist_entries')->first();$token=Waitlist::data($row)['token'];$this->postJson('/api/waitlist/token/'.$token,['action'=>'confirm'])->assertOk();$this->assertSame(0,Waitlist::run()['queued']);app(SalonStore::class)->mutate(function(&$s){$s['bookings'][0]['status']='cancelled';});Time::setTestNow(now()->addMinutes(3));$this->assertSame(1,Waitlist::run()['queued']);app(SalonStore::class)->mutate(function(&$s){$s['bookings'][0]['status']='confirmed';});app(Notifications::class)->run();Mail::assertNothingSent();$this->assertSame('active',DB::table('waitlist_entries')->value('status'));}
 public function test_waitlist_cancel_invalid_preferences_and_other_provider_isolation():void{$this->postJson('/api/waitlist/join',$this->waitlist(['consent'=>false]))->assertUnprocessable();$this->postJson('/api/waitlist/join',$this->waitlist(['services'=>['missing']]))->assertUnprocessable();$this->postJson('/api/waitlist/join',$this->waitlist())->assertStatus(202);$row=DB::table('waitlist_entries')->first();$v=Waitlist::data($row);$this->withSession(['provider_id'=>2]);$this->getJson('/api/waitlist')->assertExactJson([]);$this->deleteJson('/api/waitlist/'.$row->id)->assertNotFound();$this->postJson('/api/waitlist/token/'.$v['token'],['action'=>'cancel'])->assertOk();$this->assertSame('cancelled',DB::table('waitlist_entries')->value('status'));$this->assertSame(0,Waitlist::run()['queued']);}
 public function test_manual_invite_works_with_automatic_invites_off_and_is_rate_limited():void{$this->email();app(SalonStore::class)->mutate(function(&$s){$s['settings']['guestInvitationPolicy']='none';$s['settings']['guestInvitationSmsEnabled']=false;$s['clients']=[['id'=>'unlinked','name'=>'Vendég','email'=>'invite@example.com','phone'=>'06301234567']];});$this->postJson('/api/clients/unlinked/invite',['channel'=>'email'])->assertOk()->assertJsonPath('queued',true);app(Notifications::class)->run();Mail::assertSent(\App\Mail\NotificationMail::class,1);$this->postJson('/api/clients/unlinked/invite',['channel'=>'email'])->assertUnprocessable();$this->postJson('/api/clients/unlinked/invite',['channel'=>'sms'])->assertUnprocessable();$this->withSession(['provider_id'=>2]);$this->postJson('/api/clients/unlinked/invite',['channel'=>'email'])->assertNotFound();}
 public function test_unregistered_message_requires_email_copy_and_sends_the_actual_text():void{$this->email();app(SalonStore::class)->mutate(function(&$s){$s['clients']=[['id'=>'unlinked','name'=>'Vendég','email'=>'letter@example.com']];});$this->postJson('/api/messages',['clientId'=>'unlinked','text'=>'Fontos időpontváltozás'])->assertUnprocessable();$this->postJson('/api/messages',['clientId'=>'unlinked','text'=>'Fontos időpontváltozás','emailCopy'=>true])->assertCreated();app(Notifications::class)->run();Mail::assertSent(\App\Mail\NotificationMail::class,fn($m)=>str_contains($m->contentHtml,'Fontos időpontváltozás'));$this->getJson('/api/deliveries')->assertOk()->assertJsonPath('0.description','Üzenet értesítése')->assertJsonMissingPath('0.payload');}
 public function test_prepayment_is_off_by_default_and_a_partial_card_payment_is_exactly_credited_once():void{$b=$this->booking();app(SalonStore::class)->mutate(function(&$s)use($b){$s['bookings']=[$b];});app(Connections::class)->save(['stripe_key'=>'fake','stripe_webhook_secret'=>'webhook-secret']);$this->postJson('/api/manage/checkout',['token'=>$b['token'],'mode'=>'deposit'])->assertUnprocessable();Http::assertNothingSent();app(SalonStore::class)->mutate(function(&$s){$s['settings']['prepaymentEnabled']=true;$s['settings']['prepaymentMode']='deposit';$s['settings']['depositType']='percent';$s['settings']['depositValue']=30;$s['settings']['prepaymentAccount']='12345678-12345678';$s['settings']['prepaymentAccountName']='Szalon';});Http::fake(['api.stripe.com/v1/checkout/sessions'=>Http::response(['id'=>'cs_deposit','url'=>'https://checkout.stripe.com/c/pay/deposit'])]);$this->postJson('/api/manage/checkout',['token'=>$b['token'],'mode'=>'deposit','amount'=>1])->assertOk();$this->postJson('/api/manage/checkout',['token'=>$b['token'],'mode'=>'deposit'])->assertOk();Http::assertSentCount(1);Http::assertSent(fn($r)=>$r['line_items'][0]['price_data']['unit_amount']===300000);$object=['id'=>'cs_deposit','payment_status'=>'paid','currency'=>'huf','amount_total'=>300000];$this->postWebhook($object)->assertOk();$this->postWebhook($object)->assertOk();$this->assertCount(1,app(SalonStore::class)->read()['payments']);$this->getJson('/api/manage?token='.$b['token'])->assertJsonPath('prepayment.paid',3000)->assertJsonPath('prepayment.balance',7000)->assertJsonPath('prepayment.deposit',0)->assertJsonPath('prepayment.account','12345678-12345678');$this->getJson('/api/public')->assertJsonMissingPath('settings.prepaymentAccount');}
 public function test_fixed_deposit_cannot_exceed_total_and_percent_above_100_is_rejected():void{$s=app(SalonStore::class)->read();$s['settings']['prepaymentMode']='deposit';$s['settings']['depositType']='fixed';$s['settings']['depositValue']=50000;$this->assertSame(10000,BookingPrepayments::info($s,$this->booking())['deposit']);$this->putJson('/api/config',['settings'=>['name'=>'Szalon','profession'=>'Fodrászat','confirmation'=>false,'reminder'=>24,'channel'=>'email','depositType'=>'percent','depositValue'=>150]])->assertUnprocessable();}
 public function test_cancellation_preserves_paid_access_and_stops_new_periods_then_manual_resume_has_no_backdated_charge():void{app(SalonStore::class)->mutate(function(&$s){$s['subscription']=['plan'=>'basic','status'=>'active','trialStartedAt'=>'2036-02-01T00:00:00Z','trialEndsAt'=>'2036-04-01T00:00:00Z','paidUntil'=>'2036-06-01T00:00:00Z'];});$this->postJson('/api/subscription/renewal',['renew'=>false,'confirmed'=>true])->assertOk();$s=app(SalonStore::class)->read();$this->assertSame('2036-06-01T00:00:00Z',$s['subscription']['cancelAt']);$this->assertFalse($s['subscription']['calendarBlocked']);Time::setTestNow('2036-09-15T06:00:00Z');$s=app(SalonStore::class)->read();$this->assertSame('canceled',$s['subscription']['status']);$this->assertCount(0,array_filter($s['subscription']['charges'],fn($c)=>$c['kind']==='monthly'&&Time::parse($c['from'])->gte(Time::parse('2036-06-01'))));$this->postJson('/api/subscription/renewal',['renew'=>true,'confirmed'=>true])->assertOk();$s=app(SalonStore::class)->read();$this->assertNull($s['subscription']['cancelAt']);$months=array_values(array_filter($s['subscription']['charges'],fn($c)=>$c['kind']==='monthly'&&Time::parse($c['from'])->gte(Time::parse('2036-06-01'))));$this->assertCount(1,$months);$this->assertSame('2036-09-15',substr($months[0]['from'],0,10));}
 public function test_stripe_renewal_uses_central_account_and_requires_verified_response():void{config(['integrations.platform_stripe.key'=>'central-key']);app(SalonStore::class)->mutate(function(&$s){$s['subscription']=['id'=>'sub_own','plan'=>'basic','status'=>'active','paidUntil'=>'2036-06-01T00:00:00Z'];});Http::fake(function($r){$this->assertSame('Bearer central-key',$r->header('Authorization')[0]);return Http::response(['id'=>'sub_own','status'=>'active','cancel_at_period_end'=>$r->method()==='POST','current_period_end'=>Time::parse('2036-06-01')->timestamp]);});$this->postJson('/api/subscription/renewal',['renew'=>false,'confirmed'=>true])->assertOk()->assertJsonPath('renewalEnabled',false);$this->assertNotNull(app(SalonStore::class)->read()['subscription']['cancelAt']);Http::assertSentCount(2);}
 public function test_diagnostics_are_aggregated_sanitized_and_only_visible_to_superadmin():void{SystemIssues::record('sms','timeout','Az SMS eredményét ellenőrizni kell.',1);SystemIssues::record('sms','timeout','Az SMS eredményét ellenőrizni kell.',1);$this->assertSame(1,DB::table('system_issues')->count());$this->assertSame(1,(int)DB::table('system_issues')->value('occurrences'));SystemIssues::capture(new \RuntimeException('secret token and guest@example.com'),'application',1);$this->assertStringNotContainsString('guest@example.com',json_encode(DB::table('system_issues')->get()));$this->getJson('/api/platform/issues')->assertForbidden();$this->withSession(['platform_admin'=>true]);$this->getJson('/api/platform/issues')->assertOk()->assertJsonCount(2,'issues')->assertJsonPath('retentionDays',30);$id=DB::table('system_issues')->value('id');$this->patchJson('/api/platform/issues',['id'=>$id,'resolved'=>true])->assertOk();$this->assertTrue((bool)DB::table('system_issues')->where('id',$id)->value('resolved'));}
 public function test_editor_can_manage_only_their_own_provider_reminders():void{
  app(SalonStore::class)->mutate(function(&$s){$s['settings']['businessMode']='team';$s['subscription']=['plan'=>'pro','status'=>'active'];});$other=$this->postJson('/api/provider-reminders',$this->reminder())->assertOk()->json('id');$member=$this->postJson('/api/provider-members',['staff_id'=>'eszter','email'=>'worker@example.com','role'=>'editor','password'=>'Worker-password-long','password_confirmation'=>'Worker-password-long'])->assertCreated()->json();$this->withSession(['admin'=>true,'provider_id'=>1,'provider_member_id'=>$member['id'],'provider_member_version'=>1,'provider_auth_method'=>'member']);$this->getJson('/api/provider-reminders?from=2036-05-06&to=2036-05-07')->assertOk()->assertJsonCount(0,'reminders');$this->putJson('/api/provider-reminders/'.$other,$this->reminder())->assertNotFound();$this->postJson('/api/provider-reminders',$this->reminder())->assertForbidden();$this->postJson('/api/provider-reminders',$this->reminder(['staffId'=>'eszter']))->assertOk();$this->getJson('/api/waitlist')->assertForbidden();$this->postJson('/api/subscription/renewal',['renew'=>false,'confirmed'=>true])->assertForbidden();
 }
 public function test_waitlist_mail_failure_is_logged_without_repeated_automatic_send():void{
  $this->email();$this->postJson('/api/waitlist/join',$this->waitlist())->assertStatus(202);$row=DB::table('waitlist_entries')->first();$token=Waitlist::data($row)['token'];$this->postJson('/api/waitlist/token/'.$token,['action'=>'confirm'])->assertOk();Waitlist::run();Mail::swap(new class {public function purge($name=null){}public function to($recipient){throw new \RuntimeException('private mail details');}});app(Notifications::class)->run();$this->assertSame('unknown',DB::table('waitlist_entries')->value('status'));$this->assertSame(1,DB::table('deliveries')->where('status','unknown')->count());$this->assertGreaterThan(0,DB::table('system_issues')->count());$this->assertStringNotContainsString('private mail details',json_encode(DB::table('system_issues')->get()));
 }

 public function test_waitlist_is_off_by_default_and_disabling_pauses_pending_notifications():void{
  $fresh=\App\Services\Settings::upgrade(SalonStore::initial());$this->assertFalse($fresh['settings']['waitlistEnabled']);app(SalonStore::class)->mutate(function(&$s){$s['settings']['waitlistEnabled']=false;});$this->postJson('/api/waitlist/join',$this->waitlist())->assertUnprocessable();app(SalonStore::class)->mutate(function(&$s){$s['settings']['waitlistEnabled']=true;});$this->postJson('/api/waitlist/join',$this->waitlist())->assertStatus(202);app(SalonStore::class)->mutate(function(&$s){$s['settings']['waitlistEnabled']=false;});$this->email();app(Notifications::class)->run();Mail::assertNothingSent();$this->assertSame('blocked',DB::table('deliveries')->value('status'));$this->assertSame('pending',DB::table('waitlist_entries')->value('status'));
 }

}
